INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Ischaemic Stroke — Acute Management','easy','mcq','What is the maximum time window from symptom onset within which intravenous alteplase (tPA) can be administered for acute ischaemic stroke?','["A. 4.5 hours","B. 3 hours","C. 12 hours","D. 6 hours"]','A','IV alteplase is licensed for use up to 4.5 hours from symptom onset in eligible patients. Beyond this window the risk of haemorrhagic transformation outweighs benefit. The earlier treatment is given within this window, the greater the benefit.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Ischaemic Stroke — Acute Management','easy','mcq','Which of the following is an ABSOLUTE contraindication to IV thrombolysis with tPA in acute ischaemic stroke?','["A. Age over 80 years","B. Blood pressure of 175/95 mmHg","C. Previous intracranial haemorrhage","D. Mild stroke with NIHSS score of 4"]','C','Previous intracranial haemorrhage is an absolute contraindication to tPA due to risk of re-bleeding. Age over 80 is a relative contraindication in some guidelines but not absolute. BP must be <185/110 mmHg before administration.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Ischaemic Stroke — Acute Management','easy','mcq','In the Ghana STG, what is the recommended first-line antiplatelet agent for ischaemic stroke and TIA?','["A. Aspirin 300 mg stat then 75 mg daily","B. Clopidogrel 75 mg daily","C. Dipyridamole 200 mg twice daily","D. Warfarin with target INR 2 to 3"]','A','The Ghana STG recommends aspirin 300 mg stat followed by 75 mg daily as first-line treatment for ischaemic stroke and TIA. A statin (atorvastatin 40-80 mg or rosuvastatin 20-40 mg daily) is added for secondary prevention.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Ischaemic Stroke — Acute Management','medium','mcq','A 62-year-old man presents with sudden-onset left hemiplegia and dysarthria. CT head shows no haemorrhage. BP is 190/105 mmHg. He last felt well 2 hours ago. What is the most appropriate immediate management?','["A. Lower BP to <185/110 mmHg and administer IV alteplase if no other contraindications","B. Lower BP urgently to <140/90 mmHg then give aspirin","C. Administer IV heparin infusion immediately","D. Give aspirin 300 mg and arrange elective MRI"]','A','Before thrombolysis, BP must be lowered to <185/110 mmHg. Once this threshold is achieved and contraindications excluded, IV alteplase (0.9 mg/kg, max 90 mg) should be given urgently. Heparin is not indicated acutely; aspirin alone is insufficient within the thrombolysis window.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Ischaemic Stroke — Acute Management','medium','mcq','Which NIHSS score range and imaging finding best identifies a patient likely to benefit from mechanical thrombectomy for large vessel occlusion?','["A. NIHSS 6 or more with proximal large vessel occlusion on CTA within 24 hours","B. NIHSS 2 or more with any ischaemic change on CT","C. NIHSS 20 or more only, regardless of imaging","D. Any NIHSS score if CT is normal"]','A','Mechanical thrombectomy is indicated for anterior circulation large vessel occlusion (ICA, M1, proximal M2) in patients with NIHSS 6 or more, good pre-morbid function, within 6 hours (or up to 24 hours with favourable perfusion imaging). CT angiography identifies eligible vessels.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Ischaemic Stroke — Acute Management','medium','mcq','A patient with acute ischaemic stroke is found to have atrial fibrillation on ECG. After the acute phase, which agent is most appropriate for long-term secondary prevention?','["A. Aspirin 75 mg daily indefinitely","B. Clopidogrel plus aspirin dual antiplatelet therapy","C. Oral anticoagulation (warfarin or DOAC)","D. Subcutaneous low molecular weight heparin long-term"]','C','AF-related cardioembolic stroke requires anticoagulation for secondary prevention — warfarin (INR 2-3) or a DOAC. Antiplatelet therapy alone is inferior. Anticoagulation is typically started 2-4 weeks after the stroke to avoid haemorrhagic transformation. The Ghana STG notes anticoagulation for AF.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Ischaemic Stroke — Acute Management','medium','mcq','On the NIHSS, which domain assesses the patient''s ability to maintain conjugate horizontal eye movements toward a target?','["A. Best gaze","B. Best language","C. Limb ataxia","D. Facial palsy"]','A','The NIHSS Best gaze item (item 2) tests conjugate horizontal eye movements. It scores 0 (normal), 1 (partial gaze palsy), or 2 (forced deviation or total gaze paresis). This item detects frontal eye field or pontine lesions common in stroke.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Ischaemic Stroke — Acute Management','medium','mcq','A 58-year-old woman presents 3 hours after stroke onset. Her NIHSS is 14. CT shows early ischaemic changes in less than one-third of the MCA territory. BP is 178/100 mmHg after labetalol. Which statement about tPA is most accurate?','["A. Early ischaemic CT changes are an absolute contraindication to tPA","B. tPA is contraindicated because her NIHSS exceeds 10","C. tPA can be given once BP is below 185/110 mmHg; early CT changes involving less than one-third of the MCA territory are not a contraindication","D. tPA is only for posterior circulation strokes"]','C','Early ischaemic changes involving less than one-third of the MCA territory on CT are NOT a contraindication to tPA; involvement of more than one-third IS a contraindication due to high haemorrhagic transformation risk. After BP control to <185/110 mmHg, thrombolysis can proceed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Ischaemic Stroke — Acute Management','hard','mcq','A 70-year-old man woke up with right arm weakness and aphasia with unknown exact onset. MRI DWI shows a small cortical infarct; FLAIR shows no signal change in the same area. Which conclusion is most appropriate?','["A. FLAIR-DWI mismatch indicates the infarct is likely within 4.5 hours of onset — thrombolysis may be considered","B. FLAIR-DWI mismatch suggests the stroke occurred more than 4.5 hours ago — tPA is contraindicated","C. Absence of FLAIR change means CT must be repeated before any treatment decision","D. Wake-up stroke is always a contraindication to reperfusion therapy"]','A','DWI-FLAIR mismatch (DWI positive, FLAIR negative) indicates the ischaemic lesion is likely less than 4.5 hours old, even in wake-up stroke where onset is unknown. The WAKE-UP trial demonstrated that IV alteplase guided by DWI-FLAIR mismatch improves outcomes in these patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Ischaemic Stroke — Acute Management','hard','mcq','A 65-year-old hypertensive woman with no known AF presents with acute ischaemic stroke. Echo reveals a patent foramen ovale (PFO). Duplex shows a proximal DVT in her left leg. She is not a thrombolysis candidate. What is the most appropriate secondary prevention strategy?','["A. Anticoagulation with warfarin given the high-risk PFO plus DVT suggesting paradoxical embolism","B. Aspirin alone lifelong","C. Carotid endarterectomy urgently","D. Dual antiplatelet therapy for 90 days then aspirin alone"]','A','A DVT with PFO strongly suggests paradoxical embolism as the stroke mechanism. In this context anticoagulation is preferred over antiplatelet therapy to treat the DVT and prevent further paradoxical embolism. High-risk PFO features (large shunt, atrial septal aneurysm) may also prompt PFO closure discussion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed')
,
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Haemorrhagic Stroke & SAH','easy','mcq','What is the classic headache description of subarachnoid haemorrhage?','["A. Sudden-onset thunderclap headache reaching maximal intensity within seconds, often described as the worst headache of life","B. Unilateral throbbing headache with nausea lasting 4 to 72 hours","C. Band-like bifrontal headache relieved by simple analgesia","D. Progressive occipital headache worsening over weeks with early morning vomiting"]','A','SAH classically presents with a thunderclap headache — sudden onset, reaching peak intensity within seconds to 1-2 minutes, described as the worst headache ever experienced. It may be associated with neck stiffness, photophobia, vomiting, and transient loss of consciousness.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Haemorrhagic Stroke & SAH','easy','mcq','Which drug is used to reduce cerebral vasospasm following subarachnoid haemorrhage?','["A. Verapamil","B. Amlodipine","C. Nimodipine","D. Nifedipine"]','A','Nimodipine (a dihydropyridine calcium channel blocker) 60 mg every 4 hours for 21 days is standard care after SAH. It reduces vasospasm and improves neurological outcome, though its mechanism may be partly neuroprotective rather than purely vasodilatory.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Haemorrhagic Stroke & SAH','easy','mcq','In intracerebral haemorrhage (ICH), what is the target systolic blood pressure recommended to limit haematoma expansion in patients presenting within 6 hours?','["A. Below 140 mmHg","B. Below 180 mmHg","C. Below 120 mmHg","D. Below 160 mmHg"]','A','Current evidence (INTERACT2, ATACH-2 trials) supports rapid lowering of systolic BP to below 140 mmHg in acute ICH to limit haematoma expansion, provided onset is within 6 hours and no contraindications exist. The Ghana STG advises gradual BP reduction of no more than 20% over 24 hours for haemorrhagic stroke.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Haemorrhagic Stroke & SAH','medium','mcq','A 55-year-old man on warfarin (INR 3.8) develops sudden-onset left hemiplegia. CT shows a right basal ganglia haemorrhage with midline shift. What is the most urgent pharmacological intervention?','["A. Administer IV prothrombin complex concentrate (PCC) to reverse anticoagulation urgently, plus vitamin K","B. Give vitamin K alone and observe","C. Hold warfarin and start IV heparin","D. Transfuse fresh frozen plasma only"]','A','In warfarin-associated ICH, urgent reversal with IV prothrombin complex concentrate (PCC — factors II, VII, IX, X) is faster and more effective than FFP. Vitamin K IV is given concurrently for sustained reversal. FFP alone is too slow and requires large volumes. Heparin is absolutely contraindicated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Haemorrhagic Stroke & SAH','medium','mcq','A 48-year-old woman presents with thunderclap headache. CT head is normal. What is the next most important investigation?','["A. Lumbar puncture looking for xanthochromia","B. MRI brain with gadolinium","C. EEG","D. CT angiography of the carotid arteries"]','A','A normal CT does not exclude SAH — sensitivity falls to 85-90% after 6 hours. Lumbar puncture (performed more than 12 hours after headache onset) looking for xanthochromia (yellow discolouration from haemoglobin breakdown) is mandatory when CT is negative and clinical suspicion remains high. CT angiography follows if LP is positive.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Haemorrhagic Stroke & SAH','medium','mcq','In the Hunt-Hess grading system for SAH, a Grade III patient is best described as:','["A. Asymptomatic or mild headache with no neurological deficit","B. Moderate to severe headache and neck stiffness with no deficit other than cranial nerve palsy","C. Drowsy or confused with mild focal neurological deficit","D. Deep coma with decerebrate posturing"]','C','Hunt-Hess Grade III: drowsy or confused with mild focal neurological deficit. Grade I: asymptomatic or mild headache. Grade II: severe headache and neck stiffness, no deficit. Grade IV: stupor with moderate hemiparesis. Grade V: deep coma and decerebrate posturing. Higher grade predicts poorer prognosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Haemorrhagic Stroke & SAH','medium','mcq','The Fisher grade on CT scan in SAH is used to predict risk of which complication?','["A. Hydrocephalus","B. Re-bleeding from the aneurysm","C. Cerebral vasospasm causing delayed ischaemia","D. Post-SAH seizures"]','C','The Fisher grade classifies the amount and pattern of subarachnoid blood on CT and predicts the risk of delayed cerebral ischaemia due to vasospasm. Fisher Grade 3 (thick clot more than 1 mm in subarachnoid space) carries the highest risk of vasospasm occurring 4-14 days after SAH.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Haemorrhagic Stroke & SAH','medium','mcq','A 60-year-old man has confirmed SAH from a ruptured anterior communicating artery aneurysm. He is Hunt-Hess Grade II. What is the definitive management to prevent re-bleeding?','["A. Surgical clipping or endovascular coiling of the aneurysm","B. Conservative management with nimodipine and BP control only","C. Lumbar drain insertion","D. Stereotactic radiosurgery"]','A','Definitive aneurysm treatment (surgical clipping or endovascular coiling) is essential to prevent re-bleeding, which carries 50-60% mortality. The ISAT trial showed coiling has better outcomes for most aneurysms. The choice depends on aneurysm morphology, location, and patient factors.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Haemorrhagic Stroke & SAH','hard','mcq','A 52-year-old woman develops drowsiness and new right hemiplegia 8 days after SAH from a ruptured MCA aneurysm coiled on day 2. CT shows no re-bleeding or hydrocephalus. What is the most likely diagnosis and treatment?','["A. Cerebral vasospasm causing delayed ischaemia — consider induced hypertension and intra-arterial verapamil or angioplasty","B. Re-bleeding — arrange urgent re-coiling","C. Seizure with Todd paralysis — start levetiracetam","D. Communicating hydrocephalus — insert VP shunt"]','A','Delayed cerebral ischaemia (DCI) due to vasospasm peaks at days 4-14 post-SAH. With the aneurysm secured, treatment involves induced hypertension (Triple-H therapy historically) plus intra-arterial vasodilators or balloon angioplasty for refractory vasospasm. Nimodipine must be continued.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Haemorrhagic Stroke & SAH','hard','mcq','An 80-year-old hypertensive man with a small lobar occipital haemorrhage is on aspirin for ischaemic heart disease. Gradient echo MRI shows multiple cortical microbleeds. What is the most likely underlying cause of the ICH?','["A. Cerebral amyloid angiopathy (CAA)","B. Hypertensive arteriolosclerosis","C. Arteriovenous malformation","D. Cavernous malformation"]','A','Lobar haemorrhage with multiple cortical microbleeds on GRE or SWI MRI in an elderly patient strongly suggests cerebral amyloid angiopathy (CAA). CAA involves amyloid deposition in cortical vessel walls, causing recurrent lobar bleeds. Hypertensive ICH typically affects deep structures (basal ganglia, thalamus, pons, cerebellum).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed')
,
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Epilepsy — Diagnosis & Management','easy','mcq','According to the Ghana STG, what is the FIRST-LINE drug for acute seizure termination in adults?','["A. Lorazepam IV","B. Diazepam IV","C. Phenobarbital IM","D. Phenytoin IV"]','A','The Ghana STG recommends lorazepam slow IV (4 mg as a single dose, repeated once after 10 minutes) as first-line treatment for acute seizures in adults. Lorazepam has a longer duration of anticonvulsant action than diazepam, making it preferable for acute seizure termination.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Epilepsy — Diagnosis & Management','easy','mcq','How is status epilepticus defined?','["A. Seizures without regaining consciousness between attacks, or a single seizure lasting more than 5 minutes","B. Any seizure lasting more than 2 minutes","C. Seizures refractory to two first-line anticonvulsants","D. Three or more seizures in a 24-hour period"]','A','Status epilepticus is defined as continuous seizure activity for more than 5 minutes, or recurrent seizures without return to baseline consciousness between them. This definition guides urgent treatment, as prolonged seizures cause neuronal injury and have increasing mortality.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Epilepsy — Diagnosis & Management','easy','mcq','Which antiepileptic drug is the first-line treatment for childhood absence seizures according to the Ghana STG?','["A. Carbamazepine","B. Phenytoin","C. Sodium valproate or ethosuximide","D. Levetiracetam"]','C','The Ghana STG recommends sodium valproate or ethosuximide for generalised absence seizures. Carbamazepine and phenytoin may worsen absence seizures and are contraindicated for this type. Valproate is preferred when both absence and generalised tonic-clonic seizures co-exist.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Epilepsy — Diagnosis & Management','medium','mcq','A 25-year-old woman presents with her first witnessed tonic-clonic seizure lasting 2 minutes followed by post-ictal confusion. Which investigation is most important to perform?','["A. Blood glucose, electrolytes, calcium, MRI brain, and EEG","B. EEG alone is sufficient","C. CT head with contrast and ECG only","D. Lumbar puncture only"]','A','First seizure workup requires: blood glucose (hypoglycaemia is treatable), electrolytes (Na, Ca, Mg), FBC, LFTs, toxicology screen, MRI brain (preferred over CT for structural lesions), and EEG. LP is indicated if meningitis or encephalitis is suspected. This identifies symptomatic causes before committing to AED therapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Epilepsy — Diagnosis & Management','medium','mcq','In the status epilepticus protocol, if lorazepam has failed to terminate seizures after two doses, what is the next step?','["A. Administer IV phenytoin or IV levetiracetam as second-line therapy","B. Repeat lorazepam up to four additional times","C. Give oral sodium valproate via nasogastric tube","D. Proceed directly to general anaesthesia with propofol"]','A','The status epilepticus ladder: (1) benzodiazepine (lorazepam or midazolam), then (2) IV phenytoin (15-20 mg/kg, max 50 mg/min with ECG monitoring) or IV levetiracetam or IV valproate, then (3) refractory status — intubation plus anaesthetic infusion (propofol, midazolam, thiopental). The Ghana STG supports phenytoin IV as second-line.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Epilepsy — Diagnosis & Management','medium','mcq','Which antiepileptic drug is the preferred first-line agent for focal (partial) seizures according to the Ghana STG?','["A. Ethosuximide","B. Sodium valproate","C. Carbamazepine","D. Clonazepam"]','C','The Ghana STG recommends carbamazepine as first-line for focal seizures. Carbamazepine is a sodium channel blocker with proven efficacy for focal onset seizures. Ethosuximide is only for absence seizures. Valproate is preferred for generalised seizures.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Epilepsy — Diagnosis & Management','medium','mcq','A woman with epilepsy on sodium valproate wishes to become pregnant. What is the most important counselling point?','["A. Valproate carries the highest risk of major congenital malformations and neurodevelopmental impairment among AEDs — switch before conception is strongly recommended","B. Valproate is safe in pregnancy and should be continued unchanged","C. AEDs should be stopped completely during the first trimester","D. All AEDs carry equal teratogenic risk so current treatment should continue"]','A','Sodium valproate has the highest teratogenic risk of all AEDs (spina bifida, cardiac defects, neurodevelopmental delay including autism and lower IQ). Women of childbearing potential should not receive valproate unless no alternatives exist. Switching to lamotrigine or levetiracetam before conception is recommended. Folic acid 5 mg daily is advised.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Epilepsy — Diagnosis & Management','hard','mcq','A 19-year-old man has early morning myoclonic jerks, occasional absence seizures, and generalised tonic-clonic seizures on waking. EEG shows 3-4 Hz polyspike-wave discharges. What is the most likely diagnosis and appropriate first-line AED?','["A. Childhood absence epilepsy — ethosuximide","B. Focal epilepsy with secondary generalisation — carbamazepine","C. Juvenile myoclonic epilepsy (JME) — sodium valproate (or levetiracetam in women of childbearing age)","D. Lennox-Gastaut syndrome — clobazam"]','C','Juvenile myoclonic epilepsy (JME) presents in adolescence with morning myoclonus, absence seizures, and generalised tonic-clonic seizures precipitated by sleep deprivation or alcohol. EEG shows polyspike-wave at 3-6 Hz. Sodium valproate is highly effective but teratogenic; levetiracetam is preferred in women of childbearing potential.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Epilepsy — Diagnosis & Management','hard','mcq','A 35-year-old patient with epilepsy develops fever, confusion, and skin rash with lymphadenopathy after starting a new antiepileptic drug. Eosinophilia is noted on FBC. Which AED is most likely responsible and what is the syndrome?','["A. Phenobarbital causing acute liver failure","B. Levetiracetam causing Stevens-Johnson syndrome","C. Phenytoin or carbamazepine causing Drug Reaction with Eosinophilia and Systemic Symptoms (DRESS)","D. Sodium valproate causing hyperammonaemia encephalopathy"]','C','DRESS syndrome is a rare but life-threatening hypersensitivity reaction associated most commonly with aromatic AEDs (phenytoin, carbamazepine, phenobarbital). Features: fever, morbilliform rash, lymphadenopathy, eosinophilia, and multiorgan involvement. The offending drug must be stopped immediately and systemic steroids considered.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Epilepsy — Diagnosis & Management','hard','mcq','A 7-year-old child presents with clusters of seizures associated with autonomic features (flushing, hypersalivation), predominantly occurring at night and lasting 1-2 minutes. Interictal EEG shows centrotemporal spikes. What is the most likely diagnosis?','["A. West syndrome","B. Temporal lobe epilepsy","C. Benign epilepsy with centrotemporal spikes (BECTS or Rolandic epilepsy)","D. Dravet syndrome"]','C','Benign epilepsy with centrotemporal spikes (BECTS) is the commonest focal epilepsy of childhood (ages 3-13). Seizures are typically nocturnal, involve hemifacial motor and sensory symptoms, autonomic features, and preserved consciousness. EEG hallmark: centrotemporal (Rolandic) spikes. Prognosis is excellent; remission by age 16 in most cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed')
,
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Parkinson''s Disease','easy','mcq','Which set of clinical features constitutes the classic triad of Parkinson''s disease?','["A. Postural tremor, chorea, hypotonia","B. Intention tremor, spasticity, hyperreflexia","C. Resting tremor, rigidity, bradykinesia","D. Action tremor, ataxia, nystagmus"]','C','The cardinal motor features of Parkinson''s disease are resting tremor (4-6 Hz, pill-rolling), cogwheel rigidity, and bradykinesia (slowness with decrement in amplitude of repetitive movements). Postural instability is a fourth feature, typically appearing later in the disease course.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Parkinson''s Disease','easy','mcq','What pathological hallmark is found in the substantia nigra pars compacta in Parkinson''s disease?','["A. TDP-43 inclusions","B. Neurofibrillary tangles","C. Lewy bodies (alpha-synuclein aggregates)","D. Senile plaques (amyloid-beta)"]','C','Parkinson''s disease is characterised by intracellular alpha-synuclein aggregates forming Lewy bodies in surviving dopaminergic neurons of the substantia nigra pars compacta. Loss of these neurons reduces striatal dopamine, causing the motor features of PD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Parkinson''s Disease','easy','mcq','At what Hoehn-Yahr stage does a patient with Parkinson''s disease first exhibit bilateral motor involvement?','["A. Stage 4","B. Stage 1","C. Stage 2","D. Stage 3"]','C','Hoehn-Yahr staging: Stage 1 = unilateral disease; Stage 2 = bilateral disease without balance impairment; Stage 3 = bilateral disease with mild balance impairment, still independent; Stage 4 = severe disability, still able to walk; Stage 5 = wheelchair-bound or bedridden.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Parkinson''s Disease','medium','mcq','A 68-year-old man with Parkinson''s disease on levodopa/carbidopa complains that his medication wears off 3-4 hours after each dose and he becomes rigid and slow before the next dose. What is this phenomenon and how is it best managed?','["A. Drug-induced parkinsonism — stop levodopa","B. On-off phenomenon — switch to dopamine agonist monotherapy","C. Wearing-off effect — increase dose frequency or add a COMT inhibitor or MAO-B inhibitor","D. Levodopa-induced dyskinesia — reduce levodopa dose"]','C','Wearing-off (end-of-dose deterioration) is a predictable return of PD symptoms before the next levodopa dose. Management options: reduce dosing interval, add a COMT inhibitor (entacapone), add a MAO-B inhibitor (rasagiline or selegiline), use controlled-release levodopa, or add a dopamine agonist.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Parkinson''s Disease','medium','mcq','Which of the following is NOT a recognised non-motor symptom of Parkinson''s disease?','["A. REM sleep behaviour disorder","B. Anosmia","C. Orthostatic hypotension","D. Cerebellar ataxia"]','D','Non-motor symptoms of PD include REM sleep behaviour disorder (often preceding motor symptoms by years), anosmia, constipation, depression, anxiety, cognitive impairment, autonomic dysfunction (orthostatic hypotension, urinary symptoms, sexual dysfunction), and pain. Cerebellar ataxia is NOT a feature of PD — its presence suggests an atypical parkinsonian syndrome such as MSA-C.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Parkinson''s Disease','medium','mcq','What is the mechanism of action of carbidopa when combined with levodopa in Parkinson''s treatment?','["A. It inhibits COMT in the striatum","B. It stimulates dopamine receptors directly","C. It inhibits peripheral DOPA decarboxylase, reducing peripheral conversion of levodopa to dopamine and increasing CNS availability","D. It blocks MAO-B in the brain to prevent dopamine breakdown"]','C','Carbidopa is a peripheral DOPA decarboxylase inhibitor. It prevents levodopa conversion to dopamine in the periphery (which cannot cross the BBB), thus increasing the proportion of levodopa reaching the brain. This allows lower levodopa doses and reduces peripheral side effects (nausea, vomiting, cardiac arrhythmias).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Parkinson''s Disease','medium','mcq','A 72-year-old man with Parkinson''s disease on levodopa develops involuntary writhing movements of his limbs occurring when his medication is at peak effect. What is this complication?','["A. Wearing-off","B. Freezing of gait","C. Peak-dose dyskinesia","D. On-off phenomenon"]','C','Peak-dose dyskinesias are involuntary choreiform or dystonic movements occurring at peak levodopa plasma levels (1-2 hours post-dose). They result from pulsatile dopaminergic stimulation. Management: reduce individual levodopa dose (and increase frequency), add amantadine (which has antidyskinetic properties), or consider deep brain stimulation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Parkinson''s Disease','hard','mcq','A 65-year-old man with Parkinson''s disease requires urgent abdominal surgery and is unable to take oral medication postoperatively for 5 days. What is the most dangerous consequence of abruptly stopping his levodopa?','["A. Parkinsonism-hyperpyrexia syndrome (a neuroleptic malignant syndrome-like reaction)","B. Acute psychosis","C. Cerebellar haemorrhage","D. Rebound hypertension"]','A','Abrupt withdrawal of dopaminergic therapy can precipitate parkinsonism-hyperpyrexia syndrome: severe rigidity, hyperthermia, autonomic instability, altered consciousness, and rhabdomyolysis — resembling NMS. It carries significant mortality. During perioperative nil-by-mouth, alternative routes (rotigotine patch, apomorphine SC) or nasogastric levodopa must be arranged.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Parkinson''s Disease','hard','mcq','A 70-year-old man presents with rapidly progressive parkinsonism, falls within the first year, no resting tremor, downward gaze palsy, and axial rigidity worse than limb rigidity with no response to levodopa. What is the most likely diagnosis?','["A. Parkinson''s disease","B. Multiple system atrophy parkinsonian type (MSA-P)","C. Progressive supranuclear palsy (PSP)","D. Corticobasal degeneration"]','C','PSP (Richardson''s syndrome) is characterised by: early postural instability and falls, vertical supranuclear gaze palsy (particularly downgaze), axial-predominant rigidity, pseudobulbar palsy, and poor levodopa response. The vertical gaze palsy is pathognomonic. MRI may show midbrain atrophy (hummingbird sign).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Parkinson''s Disease','hard','mcq','Which of the following features best distinguishes idiopathic Parkinson''s disease from drug-induced parkinsonism?','["A. Asymmetric resting tremor, abnormal DaTscan, and no resolution after drug withdrawal","B. Response to anticholinergic medication","C. Presence of postural instability","D. Bilateral symmetric bradykinesia and rigidity"]','A','Drug-induced parkinsonism (e.g. from metoclopramide or haloperidol) tends to be bilateral and symmetric, resolves after stopping the offending drug over weeks to months, and has a normal DaTscan (dopaminergic terminals intact). Idiopathic PD is typically asymmetric with an abnormal DaTscan. Resting tremor is less common in drug-induced cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed')
,
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Dementia','easy','mcq','Which cognitive assessment tool is most widely used for screening dementia and monitoring disease progression?','["A. Mini-Mental State Examination (MMSE)","B. Hamilton Depression Rating Scale","C. Yale-Brown Obsessive Compulsive Scale","D. PHQ-9"]','A','The MMSE (maximum 30 points) tests orientation, registration, attention, recall, language, and visuospatial function. Scores 23 or below suggest cognitive impairment. The MoCA (Montreal Cognitive Assessment) is more sensitive for mild cognitive impairment. Both are used clinically to screen and monitor dementia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Dementia','easy','mcq','Which dementia is characterised by the triad of recurrent visual hallucinations, parkinsonism, and fluctuating cognition?','["A. Alzheimer''s disease","B. Frontotemporal dementia","C. Dementia with Lewy bodies","D. Vascular dementia"]','C','Dementia with Lewy bodies (DLB) core features: fluctuating cognition, recurrent detailed visual hallucinations, parkinsonism, and REM sleep behaviour disorder. Patients are exquisitely sensitive to antipsychotics (which can cause severe rigidity and accelerated decline). DaTscan shows reduced dopaminergic uptake.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Dementia','easy','mcq','Which class of medication provides symptomatic benefit in mild-to-moderate Alzheimer''s disease?','["A. Acetylcholinesterase inhibitors such as donepezil and rivastigmine","B. Dopamine agonists","C. Benzodiazepines","D. Antipsychotics"]','A','Acetylcholinesterase inhibitors (donepezil, rivastigmine, galantamine) inhibit breakdown of acetylcholine, partially compensating for cholinergic deficits in Alzheimer''s. They provide modest symptomatic improvement in cognition and function. Memantine (NMDA antagonist) is used in moderate-severe Alzheimer''s, alone or combined with cholinesterase inhibitors.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Dementia','medium','mcq','A 75-year-old man develops progressive memory loss with stepwise deterioration following two episodes of stroke. MRI shows periventricular white matter changes and multiple lacunar infarcts. What is the most likely diagnosis?','["A. Alzheimer''s disease","B. Dementia with Lewy bodies","C. Vascular dementia","D. Normal pressure hydrocephalus"]','C','Vascular dementia is characterised by cognitive decline with stepwise progression temporally related to cerebrovascular events. MRI shows extensive white matter changes (leukoaraiosis) and lacunar infarcts. Risk factors mirror those for stroke. Unlike Alzheimer''s, memory may be relatively preserved with prominent executive dysfunction early.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Dementia','medium','mcq','A 62-year-old man presents with personality change, disinhibition, compulsive eating, and loss of empathy. Memory is relatively preserved. MRI shows frontal and anterior temporal lobe atrophy. What is the most likely diagnosis?','["A. Behavioural variant frontotemporal dementia (bvFTD)","B. Dementia with Lewy bodies","C. Creutzfeldt-Jakob disease","D. Alzheimer''s disease"]','A','Behavioural variant FTD presents with early personality change, disinhibition, apathy, compulsive or ritualistic behaviour, hyperorality, and impaired social cognition with relative memory preservation — contrasting with Alzheimer''s where episodic memory is affected first. MRI shows frontal and anterior temporal predominant atrophy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Dementia','medium','mcq','What is the classical clinical triad of normal pressure hydrocephalus (NPH)?','["A. Gait apraxia, urinary incontinence, and dementia","B. Aphasia, apraxia, agnosia","C. Fluctuating cognition, hallucinations, parkinsonism","D. Memory loss, tremor, rigidity"]','A','Normal pressure hydrocephalus presents with the Hakim-Adams triad: gait apraxia (magnetic gait — wide-based, shuffling), urinary incontinence, and dementia. Gait disturbance typically appears first. Diagnosis: LP with opening pressure 70-245 mmH2O, large-volume LP tap test showing clinical improvement, and ventriculomegaly on imaging.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Dementia','medium','mcq','Why should antipsychotics be used with extreme caution in patients with dementia with Lewy bodies?','["A. They cause severe neuroleptic sensitivity reactions with worsening parkinsonism, sedation, and potentially fatal reactions","B. They worsen visual hallucinations exclusively","C. They interact with donepezil causing serotonin syndrome","D. They cause paradoxical euphoria in DLB"]','A','Patients with DLB have severe antipsychotic sensitivity: even atypical antipsychotics can cause dramatic deterioration with worsening parkinsonism, rigidity, reduced consciousness, and death. If antipsychotics are absolutely needed, quetiapine at low dose is the least risky option. This sensitivity is a key distinguishing feature of DLB.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Dementia','hard','mcq','A 68-year-old woman presents with rapidly progressive dementia over 3 months, myoclonus, visual disturbance, and cerebellar ataxia. MRI DWI shows cortical ribboning and basal ganglia signal change. EEG shows periodic sharp wave complexes. What is the most likely diagnosis?','["A. Alzheimer''s disease","B. Viral encephalitis","C. Sporadic Creutzfeldt-Jakob disease (sCJD)","D. Anti-NMDAR encephalitis"]','C','Sporadic CJD presents with rapidly progressive dementia (weeks to months), myoclonus, cerebellar ataxia, and cortical blindness. EEG shows periodic sharp wave complexes. MRI DWI: cortical ribboning and basal ganglia or thalamic signal change. CSF: elevated 14-3-3 protein; RT-QuIC (prion seeding assay) is highly specific. Universally fatal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Dementia','hard','mcq','A 55-year-old woman with known breast cancer develops subacute memory loss, confusion, and seizures over 6 weeks. CSF is mildly inflammatory. MRI shows T2 signal change in the medial temporal lobes bilaterally. Serum anti-Hu antibodies are positive. What is the most likely diagnosis?','["A. Paraneoplastic limbic encephalitis associated with anti-Hu antibodies","B. Herpes simplex encephalitis","C. Carcinomatous meningitis","D. Brain metastases"]','A','Paraneoplastic limbic encephalitis presents with subacute memory loss, seizures, psychiatric symptoms, and limbic T2/FLAIR changes bilaterally on MRI. Anti-Hu (ANNA-1) is associated with small-cell lung cancer and rarely breast cancer. Unlike synaptic autoimmune encephalitis, antibody-mediated forms often respond poorly to immunotherapy as damage is T-cell mediated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Dementia','hard','mcq','In Alzheimer''s disease, which neuropathological feature correlates best with the severity of clinical dementia?','["A. Amount of amyloid-beta in CSF","B. Cortical Lewy body count","C. Senile plaque density","D. Neurofibrillary tangle burden particularly in hippocampus and cortex"]','D','While both amyloid plaques and neurofibrillary tangles (NFTs, composed of hyperphosphorylated tau) are hallmarks of Alzheimer''s disease, the burden and spread of NFTs correlates more closely with the severity and progression of dementia. Braak staging tracks NFT spread from entorhinal cortex to hippocampus to neocortex.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed')
,
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Multiple Sclerosis','easy','mcq','What diagnostic criteria are used for multiple sclerosis, requiring demonstration of lesions disseminated in time and space?','["A. Revised Jones criteria","B. Schumacher criteria","C. Ann Arbor criteria","D. McDonald criteria"]','D','The 2017 McDonald criteria diagnose MS by demonstrating dissemination in space (DIS — lesions in 2 or more of 4 characteristic CNS locations: periventricular, cortical or juxtacortical, infratentorial, spinal cord) and dissemination in time (DIT — new T2 lesion on follow-up MRI, or simultaneous enhancing and non-enhancing lesions, or positive CSF OCBs).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Multiple Sclerosis','easy','mcq','What is the standard treatment for an acute MS relapse?','["A. Plasma exchange as first-line","B. Intramuscular beta-interferon","C. Oral prednisolone 40 mg daily for 6 weeks","D. High-dose intravenous methylprednisolone 1 g daily for 3-5 days"]','D','Acute MS relapses are treated with high-dose IV methylprednisolone 1 g per day for 3-5 days. This hastens recovery but does not affect long-term disability. Oral high-dose methylprednisolone is an equivalent alternative. Plasma exchange is reserved for severe steroid-refractory relapses.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Multiple Sclerosis','easy','mcq','What is the Uhthoff phenomenon in multiple sclerosis?','["A. Rebound neurological deterioration after steroid withdrawal","B. Bilateral internuclear ophthalmoplegia","C. Worsening of symptoms with cold exposure","D. Temporary worsening of neurological symptoms with increased body temperature such as during exercise or a hot bath"]','D','Uhthoff phenomenon: transient worsening of existing MS symptoms with elevated body temperature (exercise, fever, hot bath). It occurs because demyelinated axons are sensitive to temperature — increased temperature further impairs conduction in already demyelinated fibres. Symptoms resolve when temperature normalises. It is NOT a relapse.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Multiple Sclerosis','medium','mcq','A 28-year-old woman presents with painful loss of vision in her right eye over 3 days with a central scotoma and reduced colour vision. MRI brain shows periventricular white matter lesions. What is the most likely diagnosis?','["A. Anterior ischaemic optic neuropathy","B. Retinal detachment","C. Optic neuritis — likely a first demyelinating event (clinically isolated syndrome)","D. Central retinal artery occlusion"]','C','Optic neuritis in a young woman with periventricular lesions on MRI strongly suggests a first demyelinating event (clinically isolated syndrome, CIS) and high risk of developing MS. Features: painful monocular vision loss, central scotoma, impaired colour vision, and relative afferent pupillary defect (RAPD). MRI lesion burden predicts future MS risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Multiple Sclerosis','medium','mcq','Which CSF finding supports a diagnosis of MS?','["A. Xanthochromia","B. Turbid CSF with high neutrophil count","C. Markedly elevated protein above 2 g/L","D. Oligoclonal bands in CSF but not in serum, indicating intrathecal IgG synthesis"]','D','Oligoclonal bands (OCBs) in CSF but not in matched serum indicate intrathecal IgG synthesis and are present in more than 90% of MS patients. A CSF IgG index above 0.7 also supports intrathecal synthesis. CSF cell count is mildly elevated (lymphocytosis less than 50 cells per microlitre) and protein is mildly raised, unlike bacterial meningitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Multiple Sclerosis','medium','mcq','Which disease-modifying therapy for MS carries a risk of progressive multifocal leukoencephalopathy (PML) caused by JC virus reactivation?','["A. Interferon beta-1a","B. Glatiramer acetate","C. Natalizumab","D. Dimethyl fumarate"]','C','Natalizumab (anti-VLA-4 monoclonal antibody) prevents lymphocyte trafficking into the CNS but carries risk of PML due to JC virus reactivation, particularly in JC antibody-positive patients. Risk stratification uses anti-JC antibody index. Risk increases significantly after 24 months of treatment in JC-seropositive patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Multiple Sclerosis','medium','mcq','A 35-year-old man with MS develops bilateral internuclear ophthalmoplegia (INO). Which structure is damaged?','["A. Abducens nucleus","B. Trochlear nerve","C. Oculomotor nucleus","D. Medial longitudinal fasciculus (MLF)"]','D','INO results from a lesion in the medial longitudinal fasciculus (MLF). It causes failure of adduction on the ipsilateral side with nystagmus of the abducting contralateral eye on horizontal gaze. Bilateral INO in a young person is virtually pathognomonic of MS. A left MLF lesion impairs left eye adduction on right gaze.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Multiple Sclerosis','hard','mcq','A 30-year-old woman is diagnosed with relapsing-remitting MS. She has had two relapses in the past year, one with incomplete recovery, and MRI shows four new T2 lesions. She is JC antibody negative. Which management strategy is most appropriate?','["A. No treatment — adopt a watch-and-wait approach","B. Low-efficacy DMT (interferon beta) as she is early in disease","C. High-efficacy DMT such as natalizumab, ocrelizumab, or alemtuzumab given high disease activity","D. Treat with steroids alone and reassess in 12 months"]','C','High disease activity (2 or more relapses in 1 year with incomplete recovery plus multiple new MRI lesions) warrants a high-efficacy DMT at induction. Natalizumab is appropriate given JC-negativity. Other high-efficacy options include ocrelizumab (anti-CD20) and alemtuzumab. Early aggressive treatment reduces long-term disability accumulation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Multiple Sclerosis','hard','mcq','A 40-year-old woman presents with bilateral visual loss, severe optic neuritis, and complete transverse myelitis extending over 3 vertebral segments. AQP4-IgG antibodies are positive. Which diagnosis best fits?','["A. Acute disseminated encephalomyelitis (ADEM)","B. Neurosarcoidosis","C. Multiple sclerosis","D. Neuromyelitis optica spectrum disorder (NMOSD)"]','D','NMOSD is characterised by severe optic neuritis (often bilateral), longitudinally extensive transverse myelitis (3 or more vertebral segments), and area postrema syndrome. AQP4-IgG (aquaporin-4 antibody) is pathognomonic. NMOSD is distinct from MS — MRI lacks periventricular MS plaques, and some MS DMTs (natalizumab, fingolimod, alemtuzumab) can worsen NMOSD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Multiple Sclerosis','hard','mcq','In progressive MS, which disease-modifying therapy has demonstrated efficacy in slowing disability progression and is specifically approved for primary progressive MS?','["A. Interferon beta-1b","B. Glatiramer acetate","C. Ocrelizumab (anti-CD20 monoclonal antibody)","D. Teriflunomide"]','C','Ocrelizumab is the first DMT approved for primary progressive MS (PPMS), based on the ORATORIO trial showing significant reduction in 12-week confirmed disability progression compared to placebo. It depletes CD20-positive B cells. All other listed agents lack evidence of efficacy in PPMS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed')
,
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Meningitis & Encephalitis','easy','mcq','What is the classic clinical triad of bacterial meningitis?','["A. Fever, rash, arthralgia","B. Headache, focal neurological deficit, seizures","C. Headache, vomiting, papilloedema","D. Fever, neck stiffness, altered consciousness"]','D','Bacterial meningitis presents with the classic triad of fever, neck stiffness (meningismus), and altered consciousness. Only two-thirds of patients present with all three. Other features include photophobia, phonophobia, headache, vomiting, and Kernig''s and Brudzinski''s signs. Petechial or purpuric rash suggests meningococcal disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Meningitis & Encephalitis','easy','mcq','What is the empiric antibiotic regimen for bacterial meningitis in adults aged 18-60 years?','["A. IV penicillin G alone","B. Oral ciprofloxacin plus metronidazole","C. IV amoxicillin plus gentamicin","D. IV ceftriaxone 2 g 12-hourly plus dexamethasone"]','D','Empiric treatment for community-acquired bacterial meningitis in adults is IV ceftriaxone (2 g 12-hourly) to cover S. pneumoniae and N. meningitidis. In patients over 60 or immunocompromised, IV amoxicillin is added to cover Listeria monocytogenes. Dexamethasone 0.15 mg/kg 6-hourly for 4 days reduces mortality and neurological sequelae, particularly in pneumococcal meningitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Meningitis & Encephalitis','easy','mcq','In HSV encephalitis, which antiviral drug is the treatment of choice and what is the typical MRI finding?','["A. Foscarnet IV; frontal lobe enhancement","B. Valacyclovir oral; diffuse cerebral oedema","C. Ganciclovir IV; occipital lobe T2 signal change","D. Acyclovir IV; temporal lobe T2 and FLAIR hyperintensity"]','D','HSV-1 encephalitis characteristically involves the medial temporal lobes, orbital frontal cortex, and insular cortex, producing T2/FLAIR hyperintensity with haemorrhagic changes on MRI. IV acyclovir 10 mg/kg 8-hourly for 14-21 days is the treatment of choice. Early treatment significantly reduces mortality and morbidity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Meningitis & Encephalitis','medium','mcq','A 45-year-old man presents with fever, headache, and neck stiffness. You wish to perform a lumbar puncture. Which finding is NOT a contraindication to immediate LP?','["A. Midline shift on CT","B. Papilloedema","C. GCS of 14 with mild confusion but no focal neurology","D. Evidence of cerebral herniation on CT"]','C','Contraindications to immediate LP include: papilloedema, focal neurological deficits, GCS below 13, immunocompromise, raised ICP on CT (midline shift, obliterated basal cisterns, herniation), or coagulopathy. Mild confusion alone (GCS 14) without focal signs or CT abnormalities is NOT an absolute contraindication. If in doubt, give antibiotics immediately then CT before LP.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Meningitis & Encephalitis','medium','mcq','CSF analysis in bacterial meningitis characteristically shows which pattern?','["A. Xanthochromic fluid, red blood cells, elevated protein, normal glucose","B. Clear fluid, normal cells, very high protein, normal glucose","C. Clear fluid, lymphocytosis 50-500 cells, elevated protein, normal glucose","D. Turbid fluid, neutrophilia over 1000 cells, markedly elevated protein, glucose less than 50% serum"]','D','Bacterial meningitis CSF: turbid or purulent, neutrophilia (often more than 1000 cells/microlitre), markedly elevated protein (above 1 g/L), low glucose (less than 50% of simultaneous serum glucose). Viral meningitis: clear fluid, lymphocytosis, mildly elevated protein, normal glucose. TB meningitis: lymphocytosis, very high protein, very low glucose with a subacute time course.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Meningitis & Encephalitis','medium','mcq','When should dexamethasone be given in relation to the first antibiotic dose in bacterial meningitis?','["A. Only if the patient deteriorates after 24 hours","B. Only in children under 5 years, not adults","C. 6 hours after the first antibiotic dose","D. Simultaneously with or just before the first antibiotic dose"]','D','Dexamethasone (0.15 mg/kg IV 6-hourly for 4 days) should be given simultaneously with or just before the first antibiotic dose to maximally suppress the inflammatory response triggered by bacterial lysis. Benefit is substantially reduced if given after antibiotics. It is most beneficial in pneumococcal meningitis in adults.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Meningitis & Encephalitis','medium','mcq','A 30-year-old man presents with 5 days of fever, personality change, and temporal lobe seizures. MRI shows bilateral temporal lobe FLAIR signal change. HSV PCR on CSF is negative. Anti-NMDAR antibodies are positive. What is the most appropriate treatment?','["A. Start antiretroviral therapy","B. Lumbar drain insertion","C. Continue IV acyclovir for 21 days","D. High-dose steroids, IVIG, or plasma exchange for autoimmune encephalitis"]','D','Anti-NMDAR receptor encephalitis is the commonest autoimmune encephalitis, often associated with ovarian teratoma in young women but also occurring in men. Features: psychiatric prodrome, seizures, movement disorders, autonomic instability, decreased consciousness. Treatment: immunotherapy (steroids, IVIG, plasmapheresis) plus rituximab or cyclophosphamide for refractory cases; remove teratoma if present.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Meningitis & Encephalitis','hard','mcq','A 65-year-old immunocompetent man presents with bacterial meningitis. Why is amoxicillin added to ceftriaxone in patients over 60 years of age?','["A. To achieve better CNS penetration","B. To reduce ceftriaxone nephrotoxicity","C. To broaden cover against Pseudomonas aeruginosa","D. To cover Listeria monocytogenes, which is intrinsically resistant to cephalosporins"]','D','Listeria monocytogenes is an important cause of bacterial meningitis in the elderly (over 60), neonates, and immunocompromised patients. Listeria is intrinsically resistant to all cephalosporins. Amoxicillin (or ampicillin) is the drug of choice for Listeria coverage. Ceftriaxone alone is insufficient in these age groups.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Meningitis & Encephalitis','hard','mcq','A 35-year-old HIV-positive man (CD4 count 50 cells/microlitre) presents with 3 weeks of progressive headache, confusion, and cranial nerve VI palsy. CSF opening pressure is 30 cmH2O. India ink stain is positive. What is the treatment of choice?','["A. IV acyclovir","B. IV ceftriaxone plus dexamethasone","C. IV fluconazole alone","D. Liposomal amphotericin B plus flucytosine for 2 weeks induction then fluconazole consolidation"]','D','Cryptococcal meningitis in HIV (CD4 below 100) treatment: induction — liposomal amphotericin B (3-4 mg/kg/day) plus flucytosine for 2 or more weeks; consolidation — fluconazole 400 mg/day for 8 weeks; maintenance — fluconazole 200 mg/day lifelong until CD4 above 200 on ART. Raised ICP is managed with serial therapeutic LPs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Meningitis & Encephalitis','hard','mcq','A 50-year-old woman presents with 6 weeks of progressive headache, weight loss, and cranial nerve palsies. CSF shows lymphocytosis, very high protein, and very low glucose. ZN stain is negative. ADA is elevated. What is the most likely diagnosis and initial treatment?','["A. Viral meningitis — symptomatic management","B. Cryptococcal meningitis — amphotericin B","C. Bacterial meningitis — IV ceftriaxone","D. Tuberculous meningitis — HRZE quadruple therapy plus dexamethasone"]','D','TB meningitis presents subacutely with lymphocytic pleocytosis, markedly elevated protein, very low CSF glucose, and high ADA. ZN stain sensitivity is only around 40%. Treatment: 2 months of HRZE (isoniazid, rifampicin, pyrazinamide, ethambutol) followed by 10 months of HR, plus dexamethasone tapered over 6-8 weeks to reduce mortality and neurological sequelae.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed')
,
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Headache Disorders','easy','mcq','According to the ICHD-3 criteria, how many attacks are required before a diagnosis of migraine WITHOUT aura can be made?','["A. At least 1 attack","B. At least 2 attacks","C. At least 5 attacks","D. At least 10 attacks"]','C','ICHD-3 criteria for migraine without aura require at least 5 attacks lasting 4-72 hours with at least 2 of: unilateral location, pulsating quality, moderate-severe intensity, aggravation by routine activity; and at least 1 of: nausea or vomiting or photo/phonophobia. Two attacks are required for migraine with aura.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Headache Disorders','easy','mcq','What is the first-line prophylactic treatment for migraine according to the Ghana STG?','["A. Topiramate","B. Valproate","C. Amitriptyline","D. Propranolol"]','D','The Ghana STG recommends propranolol as first-line migraine prophylaxis (initial 40 mg 12-hourly, maintenance 80-120 mg 12-hourly). Propranolol is a beta-blocker with proven efficacy in reducing migraine frequency and severity. It is contraindicated in asthma, heart block, and uncontrolled heart failure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Headache Disorders','easy','mcq','A patient with cluster headache presents with a severe right-sided periorbital headache with ipsilateral lacrimation and nasal congestion. What is the most effective acute treatment?','["A. Oral ergotamine","B. IV morphine","C. Oral paracetamol 1 g","D. 100% oxygen via non-rebreather mask at 12-15 L/min or subcutaneous sumatriptan"]','D','Cluster headache acute treatment: 100% high-flow oxygen (12-15 L/min for 15-20 minutes) is highly effective and well tolerated. Subcutaneous sumatriptan 6 mg is the fastest pharmacological option. Oral triptans are too slow due to delayed absorption during attacks. The pain typically lasts 15-180 minutes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Headache Disorders','medium','mcq','A 35-year-old woman has 4 disabling migraines per month not adequately controlled with triptans. Which of the following is an appropriate preventive therapy?','["A. Naproxen only during attacks","B. Increasing triptan use to daily","C. Codeine 30 mg three times daily","D. Amitriptyline 10-75 mg nightly"]','D','Migraine prophylaxis is indicated for 4 or more attacks per month or significant disability. Options include propranolol, amitriptyline (10-75 mg), topiramate, valproate, candesartan, and CGRP monoclonal antibodies. Amitriptyline is particularly useful when migraine coexists with insomnia or depression. Daily opioids or triptans risk medication overuse headache.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Headache Disorders','medium','mcq','A 40-year-old obese woman presents with daily headaches, transient visual obscurations, and bilateral papilloedema. MRI brain is normal. CSF opening pressure is 38 cmH2O with normal constituents. What is the diagnosis?','["A. Bacterial meningitis","B. Cerebral venous sinus thrombosis","C. Migraine with brainstem aura","D. Idiopathic intracranial hypertension (pseudotumour cerebri)"]','D','Idiopathic intracranial hypertension (IIH) classically affects obese women of childbearing age. Features: daily headache, visual obscurations, papilloedema, pulsatile tinnitus, diplopia (CN VI palsy). MRI is normal or shows empty sella or slit ventricles. CSF pressure above 25 cmH2O with normal constituents. Treatment: weight loss, acetazolamide, and optic nerve sheath fenestration if vision threatened.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Headache Disorders','medium','mcq','Which headache feature is a RED FLAG requiring urgent CT brain imaging?','["A. Throbbing quality with nausea and photophobia","B. Headache relieved by lying in a quiet dark room","C. Bilateral temporal location worsening with stress","D. Thunderclap onset reaching maximum intensity within 60 seconds"]','D','Red flag features (SNOOP4 mnemonic): Systemic symptoms, Neurological signs, Onset sudden (thunderclap), Older age over 50 with new headache, Positional headache, Papilloedema, Progressive headache, Precipitated by Valsalva. Thunderclap headache mandates urgent CT brain plus LP to exclude SAH.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Headache Disorders','medium','mcq','Triptans (5-HT1B/1D agonists) are contraindicated in which patient group?','["A. Patients who are breastfeeding exclusively","B. Patients with tension-type headache","C. Patients with a history of motion sickness","D. Patients with known ischaemic heart disease or uncontrolled hypertension"]','D','Triptans cause vasoconstriction via 5-HT1B receptors on intracranial and peripheral blood vessels. They are contraindicated in ischaemic heart disease, stroke or TIA, uncontrolled hypertension, peripheral vascular disease, and hemiplegic or basilar migraine. They should not be combined with ergotamines due to additive vasospasm risk.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Headache Disorders','hard','mcq','A 55-year-old man presents with a 3-month history of unilateral left-sided headache with jaw claudication and scalp tenderness. ESR is 95 mm/hr. Visual acuity in the left eye has recently deteriorated. What is the most urgent management?','["A. Refer to ophthalmology for glasses prescription","B. Start aspirin 75 mg and observe for 2 weeks","C. Arrange temporal artery biopsy and await results before treating","D. Start prednisolone 60-80 mg daily immediately to protect vision, perform biopsy within 1-2 weeks"]','D','Giant cell (temporal) arteritis with visual involvement requires immediate high-dose prednisolone (60-80 mg/day or IV methylprednisolone if vision is threatened) to prevent permanent blindness from ischaemic optic neuropathy. Treatment must NOT wait for biopsy — biopsy can be performed within 1-2 weeks of starting steroids without significantly affecting histology.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Headache Disorders','hard','mcq','A 32-year-old man develops daily headache after taking sumatriptan more than 10 days per month for 3 months. The headache is present on waking and does not respond to analgesics. What is the diagnosis and management?','["A. Cluster headache — start verapamil","B. Tension-type headache — prescribe codeine","C. Chronic migraine — increase triptan dose","D. Medication overuse headache (MOH) — withdraw the overused medication and bridge with naproxen or amitriptyline"]','D','Medication overuse headache (MOH) occurs with triptans or ergotamines used more than 10 days per month, or simple analgesics more than 15 days per month for over 3 months. Treatment requires withdrawal of the overused medication with a bridging regimen (NSAIDs, short steroid course, amitriptyline). Headache initially worsens before improving over 2-4 weeks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Headache Disorders','hard','mcq','A 28-year-old woman on oral contraceptive pill develops a new headache with sensory aura lasting 45 minutes. She is a smoker. What is the most important management step?','["A. Switch prophylaxis to topiramate only","B. Refer for MRI and continue current management until results available","C. Prescribe a triptan and continue the OCP","D. Discontinue the oestrogen-containing OCP — migraine with aura combined with smoking and oestrogen significantly increases stroke risk"]','D','Migraine with aura combined with oestrogen-containing contraception and smoking significantly increases ischaemic stroke risk as independent multiplicative risk factors. The combined OCP should be discontinued. Non-oestrogen alternatives (progestogen-only pill, IUD, barrier methods) should be offered. This is a recognised contraindication to the combined OCP.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed')
,
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Peripheral Neuropathy & Guillain-Barré','easy','mcq','What is the classic CSF finding in Guillain-Barré syndrome (GBS)?','["A. Xanthochromia with normal protein","B. Low glucose with lymphocytosis","C. Neutrophilic pleocytosis with high protein","D. Albuminocytological dissociation — high protein with normal or mildly elevated cell count"]','D','The hallmark CSF finding in GBS is albuminocytological dissociation: markedly elevated protein (often above 1 g/L) with a normal or near-normal cell count (fewer than 10 cells per microlitre). This reflects radiculopathy with protein leakage into CSF without significant inflammatory cell infiltration. This finding typically peaks 2-4 weeks after onset.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Peripheral Neuropathy & Guillain-Barré','easy','mcq','Which two treatments are of proven benefit in Guillain-Barré syndrome?','["A. Corticosteroids and azathioprine","B. Intravenous immunoglobulin (IVIG) and plasma exchange (plasmapheresis)","C. Cyclophosphamide and mycophenolate","D. Interferon beta and natalizumab"]','B','Both IVIG (0.4 g/kg/day for 5 days) and plasma exchange (4-6 sessions over 1-2 weeks) are equally effective in GBS, speeding recovery if started within 2 weeks of onset. They are NOT combined (no additive benefit). Corticosteroids alone are NOT beneficial in GBS and may worsen outcome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Peripheral Neuropathy & Guillain-Barré','easy','mcq','What is the most common preceding infection associated with Guillain-Barré syndrome?','["A. Herpes simplex virus","B. Campylobacter jejuni","C. Streptococcus pneumoniae","D. Mycobacterium tuberculosis"]','B','Campylobacter jejuni gastroenteritis (1-3 weeks before GBS onset) is the most common identifiable trigger, particularly for axonal subtypes (AMAN, AMSAN). Other triggers include CMV, EBV, HIV, influenza, and Zika virus. Molecular mimicry between C. jejuni lipooligosaccharides and ganglioside epitopes on peripheral nerve axons is the proposed mechanism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Peripheral Neuropathy & Guillain-Barré','medium','mcq','A 40-year-old man presents with progressive ascending weakness of both legs over 5 days, bilateral facial weakness, and absent deep tendon reflexes. He had gastroenteritis 2 weeks ago. NCS shows prolonged distal latencies, reduced conduction velocities, and conduction block. What is the most likely GBS subtype?','["A. Acute motor axonal neuropathy (AMAN)","B. Acute inflammatory demyelinating polyneuropathy (AIDP)","C. Miller Fisher syndrome","D. Multifocal motor neuropathy"]','B','AIDP (the classic Western form of GBS) is characterised by ascending weakness, areflexia, and demyelinating features on NCS: prolonged distal latencies, reduced conduction velocities, prolonged F-waves, and conduction block. Bilateral facial weakness is common. AMAN shows normal or near-normal CVs with reduced CMAP amplitudes (axonal pattern).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Peripheral Neuropathy & Guillain-Barré','medium','mcq','In GBS, what is the most important immediate clinical concern that determines the need for ICU admission?','["A. Severity of limb weakness","B. Degree of sensory loss","C. Respiratory muscle involvement — FVC below 20 mL/kg indicates impending respiratory failure","D. Presence of autonomic dysfunction only"]','C','Respiratory failure is the most life-threatening complication of GBS. Serial FVC monitoring is essential: intubation is considered when FVC falls below 20 mL/kg (the 20-30-40 rule: FVC <20 mL/kg, MIP <30 cmH2O, MEP <40 cmH2O). Autonomic dysfunction (BP lability, arrhythmias) also warrants ICU monitoring.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Peripheral Neuropathy & Guillain-Barré','medium','mcq','Miller Fisher syndrome is a variant of GBS characterised by which clinical triad?','["A. Ascending weakness, areflexia, autonomic instability","B. Ophthalmoplegia, cerebellar ataxia, and areflexia","C. Facial diplegia, paraesthesiae, areflexia","D. Ptosis, diplopia, bulbar palsy"]','B','Miller Fisher syndrome (MFS) presents with the triad of ophthalmoplegia, cerebellar ataxia, and areflexia without significant limb weakness. It is associated with anti-GQ1b IgG antibodies (found in more than 90% of cases). GQ1b gangliosides are concentrated at paranodal regions of oculomotor nerves. Prognosis is generally excellent.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Peripheral Neuropathy & Guillain-Barré','medium','mcq','A 55-year-old diabetic man presents with bilateral sensory loss in a glove-and-stocking distribution, absent ankle jerks, and burning foot pain worse at night. NCS shows reduced SNAP amplitudes with preserved conduction velocities. What type of neuropathy does this pattern suggest?','["A. Demyelinating neuropathy","B. Length-dependent sensorimotor axonal neuropathy consistent with diabetic peripheral neuropathy","C. Mononeuritis multiplex","D. Pure motor neuropathy"]','B','Diabetic peripheral neuropathy is a length-dependent, distal, symmetric sensorimotor axonal neuropathy. NCS shows reduced SNAP and CMAP amplitudes with relatively preserved CVs (axonal pattern), as opposed to demyelinating neuropathies (slowed CVs, prolonged latencies). Glove and stocking distribution reflects dying-back of longest axons first.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Peripheral Neuropathy & Guillain-Barré','hard','mcq','A 35-year-old man with GBS develops severe hypertension (220/120 mmHg) alternating with hypotension, urinary retention, and heart rate of 42 bpm. What complication is this and how should it be managed?','["A. Concurrent ischaemic stroke — urgent CT brain","B. Autonomic dysfunction — cautious small doses of short-acting antihypertensives; pacemaker for sustained symptomatic bradycardia","C. Spinal cord compression — urgent MRI spine","D. Septicaemia — blood cultures and broad-spectrum antibiotics"]','B','Autonomic dysfunction occurs in up to 65% of hospitalised GBS patients. Features include BP lability, cardiac arrhythmias, urinary retention, and sweating abnormalities. Management is cautious — large antihypertensive doses risk catastrophic hypotension. Pacemaker is needed for sustained symptomatic bradycardia. Continuous cardiac monitoring is mandatory.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Peripheral Neuropathy & Guillain-Barré','hard','mcq','A 50-year-old woman presents with subacute onset of bilateral foot drop, wrist drop, and mononeuritis multiplex. She has ANCA-positive systemic vasculitis. Which neuropathy pattern is this?','["A. Length-dependent symmetric axonal neuropathy","B. Mononeuritis multiplex secondary to vasculitic neuropathy","C. Hereditary motor and sensory neuropathy","D. Toxic neuropathy from drug exposure"]','B','Mononeuritis multiplex (multiple individual nerve lesions) is caused by vasculitic neuropathy — ischaemia of individual nerve trunks from vessel wall inflammation. Associated conditions: ANCA vasculitis, PAN, rheumatoid arthritis, SLE, cryoglobulinaemia, diabetes, sarcoidosis, and leprosy. Diagnosis confirmed by nerve or muscle biopsy showing vessel wall inflammation. Treatment: immunosuppression.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Peripheral Neuropathy & Guillain-Barré','hard','mcq','A 45-year-old man presents with progressive distal weakness, absent reflexes, high arches, and hammer toes since childhood. His father has similar features. NCS shows markedly slowed motor conduction velocities below 38 m/s. What is the most likely diagnosis?','["A. Amyotrophic lateral sclerosis","B. Charcot-Marie-Tooth disease type 1 (hereditary motor and sensory neuropathy)","C. Multifocal motor neuropathy","D. Chronic inflammatory demyelinating polyneuropathy"]','B','Charcot-Marie-Tooth (CMT) type 1 is the most common hereditary neuropathy, caused by PMP22 gene duplication. Features: childhood-onset slowly progressive distal weakness and atrophy, pes cavus, hammer toes, absent reflexes, and markedly slowed NCS (CV below 38 m/s in CMT1A). Autosomal dominant inheritance. No disease-modifying treatment; management is supportive.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed')
,
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Neuromuscular Junction Disorders','easy','mcq','What is the classic clinical feature that distinguishes myasthenia gravis from most other neuromuscular disorders?','["A. Proximal muscle weakness that improves with rest","B. Fatigable weakness — weakness that worsens with sustained or repetitive activity and improves with rest","C. Weakness exclusively affecting the legs","D. Constant non-fluctuating weakness with fasciculations"]','B','MG is characterised by fatigable weakness: muscle strength decreases with sustained or repetitive effort and recovers with rest. This reflects depletion of available ACh receptors as NMJ transmission becomes increasingly unreliable with repeated stimulation. Classic tests include sustained upgaze causing ptosis and counting aloud causing dysarthria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Neuromuscular Junction Disorders','easy','mcq','Which antibody is found in approximately 85% of patients with generalised myasthenia gravis?','["A. Anti-MuSK antibody","B. Anti-AChR (acetylcholine receptor) antibody","C. Voltage-gated calcium channel antibody","D. Anti-GM1 antibody"]','B','Anti-AChR antibodies are found in approximately 85% of patients with generalised MG and about 50% of those with purely ocular MG. They are pathogenic — they reduce functional AChR at the NMJ by complement-mediated destruction, accelerated internalisation, and direct blockade. Anti-MuSK antibodies are found in many AChR-seronegative patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Neuromuscular Junction Disorders','easy','mcq','What is the pharmacological basis of the edrophonium (Tensilon) test in myasthenia gravis?','["A. It stimulates acetylcholine receptors directly","B. It inhibits acetylcholinesterase, transiently increasing ACh at the NMJ and briefly improving weakness in MG","C. It blocks voltage-gated calcium channels","D. It stimulates the motor cortex"]','B','Edrophonium is a short-acting acetylcholinesterase inhibitor. IV administration transiently increases ACh at the NMJ, improving weakness in MG patients (positive test). The test is most useful for observing ptosis improvement as an objective endpoint. Atropine must be available for cholinergic side effects. The test has been largely replaced by antibody testing and repetitive nerve stimulation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Neuromuscular Junction Disorders','medium','mcq','A 25-year-old woman with MG develops rapidly progressive dysphagia, dysarthria, and dyspnoea. FVC drops to 1.2 L. What is this complication and what is the immediate management?','["A. Cholinergic crisis — stop pyridostigmine and observe","B. Myasthenic crisis — arrange ICU admission, respiratory support, and IVIG or plasma exchange","C. Lambert-Eaton crisis — start IVIG","D. Psychogenic dyspnoea — reassure and observe"]','B','Myasthenic crisis is life-threatening deterioration of MG with respiratory failure. FVC below 1.0 L or below 20 mL/kg indicates need for intubation. Precipitants: infection, surgery, certain medications (aminoglycosides, fluoroquinolones, beta-blockers). Treatment: ICU admission, respiratory support, IVIG (0.4 g/kg/day x 5 days) or plasma exchange. Pyridostigmine may be temporarily stopped to reduce secretions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Neuromuscular Junction Disorders','medium','mcq','In myasthenia gravis, what is the current indication for thymectomy?','["A. All patients with MG regardless of thymoma status","B. All patients with thymoma, and generalised AChR-antibody positive MG aged 18-65 without thymoma where it improves long-term outcomes","C. Only patients who fail pyridostigmine","D. Only elderly patients over 70 years with severe disease"]','B','Thymectomy is recommended for: (1) all MG patients with thymoma (to remove tumour regardless of MG severity); (2) non-thymomatous AChR-antibody positive generalised MG patients aged 18-65 (MGTX trial demonstrated improved outcomes with less immunosuppression needed and better disease control). It is NOT routinely recommended for purely ocular MG or MuSK-antibody MG.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Neuromuscular Junction Disorders','medium','mcq','Lambert-Eaton myasthenic syndrome (LEMS) differs from myasthenia gravis in which important way?','["A. LEMS causes fatigable ocular and bulbar weakness predominantly","B. In LEMS, strength paradoxically increases with repeated contractions (post-tetanic potentiation), and weakness is predominantly proximal limb","C. LEMS is caused by anti-AChR antibodies","D. LEMS responds well to pyridostigmine alone"]','B','LEMS is caused by antibodies against voltage-gated calcium channels (VGCC) on presynaptic motor nerve terminals, reducing ACh release. Clinically: proximal limb weakness (legs more than arms), autonomic dysfunction (dry mouth, constipation, erectile dysfunction), depressed or absent reflexes that improve (post-tetanic potentiation) after brief exercise. Associated with small-cell lung cancer in 50-60% of cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Neuromuscular Junction Disorders','medium','mcq','Which of the following drugs should be AVOIDED in a patient with myasthenia gravis due to risk of precipitating a crisis?','["A. Prednisolone","B. Pyridostigmine","C. Aminoglycoside antibiotics such as gentamicin","D. Azathioprine"]','C','Aminoglycosides (gentamicin, tobramycin) impair presynaptic ACh release and postsynaptic receptor function, worsening NMJ transmission in MG. Other drugs to avoid: fluoroquinolones, macrolides, beta-blockers, calcium channel blockers, magnesium, neuromuscular blocking agents, chloroquine, and quinine. These can precipitate myasthenic crisis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Neuromuscular Junction Disorders','hard','mcq','A 35-year-old woman with MG on pyridostigmine develops excessive lacrimation, bradycardia, diarrhoea, and miosis after her pyridostigmine dose was accidentally doubled. What is this syndrome and what is the treatment?','["A. Myasthenic crisis — IVIG","B. Cholinergic crisis from excessive acetylcholinesterase inhibition — stop pyridostigmine immediately and give IV atropine","C. Serotonin syndrome — cyproheptadine","D. Anaphylaxis — IV adrenaline"]','B','Cholinergic crisis results from excess ACh at both nicotinic (muscle weakness, fasciculations) and muscarinic (SLUDGE: Salivation, Lacrimation, Urination, Defecation, GI cramps, Emesis, plus bradycardia, miosis, bronchospasm) receptors. Caused by overdose of acetylcholinesterase inhibitors. Treatment: stop pyridostigmine immediately, IV atropine to block muscarinic effects, respiratory support if needed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Neuromuscular Junction Disorders','hard','mcq','A 60-year-old male smoker presents with proximal leg weakness, absent knee jerks that return after 10 seconds of isometric contraction, dry mouth, and erectile dysfunction. CXR shows a hilar mass. Anti-VGCC antibodies are positive. What is the most appropriate initial management?','["A. Pyridostigmine 60 mg three times daily and reassurance","B. Urgent investigation and treatment of underlying SCLC plus amifampridine (3,4-diaminopyridine) for symptomatic LEMS","C. IV methylprednisolone for inflammatory neuropathy","D. Plasmapheresis alone"]','B','LEMS associated with SCLC is a paraneoplastic syndrome — treating the tumour is the priority and often improves LEMS. Amifampridine (3,4-diaminopyridine) enhances presynaptic ACh release by blocking K+ channels, prolonging depolarisation. IVIG and plasma exchange are used for rapid symptomatic improvement. Immunosuppression is also used long-term.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Neuromuscular Junction Disorders','hard','mcq','A 28-year-old woman with generalised MG on azathioprine and prednisolone wishes to become pregnant. Which statement is most accurate regarding MG in pregnancy?','["A. MG always worsens during pregnancy and azathioprine must be stopped immediately","B. MG course is unpredictable in pregnancy; 10-20% of neonates develop transient neonatal MG from placental transfer of maternal anti-AChR IgG","C. Plasma exchange is absolutely contraindicated in pregnancy","D. IVIG is contraindicated in the third trimester"]','B','MG in pregnancy: course is unpredictable (may improve, worsen, or remain stable). Neonatal MG occurs in 10-20% of babies born to MG mothers due to transplacental anti-AChR IgG transfer — presents with hypotonia, feeding difficulties, weak cry, resolving in weeks as maternal antibodies clear. Pyridostigmine and prednisolone are generally considered safe in pregnancy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed')
,
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Spinal Cord Disorders','easy','mcq','What is the hallmark sensory pattern of Brown-Séquard syndrome?','["A. Bilateral loss of all sensory modalities below the lesion","B. Ipsilateral loss of proprioception and vibration with contralateral loss of pain and temperature below the lesion","C. Bilateral loss of pain and temperature with preserved proprioception (central cord pattern)","D. Saddle anaesthesia with preserved lower limb sensation"]','B','Brown-Séquard (cord hemisection) syndrome: ipsilateral motor weakness (corticospinal tract) and loss of proprioception and vibration (dorsal column), plus contralateral loss of pain and temperature (spinothalamic tract crosses 1-2 levels above entry, then runs contralaterally) below the level of the lesion. Causes: trauma, tumour, MS, radiation, infection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Spinal Cord Disorders','easy','mcq','A patient presents with sudden bilateral leg weakness, saddle anaesthesia, and urinary retention after lifting a heavy object. What is the most likely diagnosis and urgency?','["A. Multiple sclerosis — refer for outpatient MRI","B. Cauda equina syndrome — surgical emergency requiring urgent MRI and decompression","C. Spinal cord transection — conservative management","D. Transverse myelitis — high-dose steroids as outpatient"]','B','Cauda equina syndrome is a surgical emergency caused by compression of cauda equina nerve roots (typically by a large central lumbar disc prolapse). Classic features: low back pain, bilateral lower limb weakness, saddle anaesthesia, urinary retention with overflow incontinence, and faecal incontinence. Urgent MRI followed by surgical decompression is required — delay worsens prognosis for sphincter recovery.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Spinal Cord Disorders','easy','mcq','What is the immediate pharmacological treatment for acute spinal cord compression due to metastatic disease?','["A. IV mannitol","B. High-dose IV dexamethasone such as 10 mg stat then 4 mg 6-hourly","C. IV methylprednisolone as in traumatic SCI protocols","D. IV ceftriaxone"]','B','For malignant spinal cord compression, high-dose dexamethasone reduces vasogenic oedema around the tumour, providing rapid neurological improvement while definitive treatment (radiotherapy or surgery) is arranged. Urgent whole-spine MRI must be obtained. Dexamethasone 10 mg IV stat followed by 4 mg 4-6 hourly is widely used.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Spinal Cord Disorders','medium','mcq','A 35-year-old woman develops acute paraplegia, urinary retention, and a sensory level at T6 over 24 hours. MRI shows T2 signal change across the full cross-sectional cord over 3 vertebral segments. AQP4-IgG is negative but MOG-IgG is positive. What is the diagnosis?','["A. MS with acute relapse","B. MOG antibody-associated disease (MOGAD) with transverse myelitis","C. Spinal cord infarction","D. Hereditary spastic paraplegia"]','B','MOG-IgG positive transverse myelitis presents with extensive cord lesions (often longitudinally extensive), complete cross-sectional involvement, and good initial response to steroids. MOGAD is distinct from both MS and NMOSD. The cord lesion tends to be conus-predominant. Treatment: acute high-dose steroids; long-term immunosuppression to prevent relapses.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Spinal Cord Disorders','medium','mcq','Which feature best distinguishes a cauda equina lesion from a conus medullaris lesion?','["A. Cauda equina lesions cause upper motor neuron signs; conus lesions cause lower motor neuron signs","B. Cauda equina lesions cause flaccid weakness with areflexia (pure LMN pattern); conus lesions may show mixed UMN and LMN features","C. Both produce identical clinical syndromes","D. Conus lesions affect the arms; cauda equina lesions affect the legs only"]','B','The conus medullaris (distal spinal cord at L1-L2) may produce mixed UMN and LMN signs because it contains both the lowest spinal cord segments and the origin of cauda equina roots. Pure cauda equina lesions (below L1) produce only LMN signs: flaccid weakness, areflexia, atrophy, saddle anaesthesia, and sphincter dysfunction without Babinski or spasticity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Spinal Cord Disorders','medium','mcq','A 60-year-old man with known prostate cancer develops back pain, bilateral leg weakness, and difficulty voiding over 48 hours. Which is the most appropriate initial investigation?','["A. Plain X-ray of the spine only","B. Urgent MRI of the whole spine with gadolinium","C. CT myelogram only","D. Bone scan and await results"]','B','Suspected malignant spinal cord compression (MSCC) requires urgent whole-spine MRI with gadolinium — it identifies the level, extent, and nature of compression, detects skip lesions, and guides treatment planning (radiotherapy versus surgical decompression). CT myelogram is an alternative if MRI is contraindicated. Start dexamethasone while awaiting imaging.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Spinal Cord Disorders','medium','mcq','A 40-year-old man presents with slowly progressive spastic paraparesis, sensory disturbance in both feet, and impaired vibration sense. MRI spine shows a posterior intradural extramedullary lesion at T4 with homogeneous gadolinium enhancement and a dural tail. What is the most likely diagnosis?','["A. Epidural abscess","B. Spinal meningioma","C. Multiple sclerosis plaque","D. Transverse myelitis"]','B','Intradural extramedullary lesions at thoracic level with dural tail sign on gadolinium-enhanced MRI are characteristic of meningioma. These are typically benign and amenable to surgical resection. They are more common in middle-aged women. Schwannoma is another differential but typically lacks the dural tail and is often associated with neurofibromatosis.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Spinal Cord Disorders','hard','mcq','A 45-year-old alcoholic man presents with subacute spastic paraparesis and impaired proprioception bilaterally. He has a sore tongue and MCV of 110 fL. MRI spine shows posterior and lateral column T2 signal change in the cervical and upper thoracic cord. What is the diagnosis?','["A. MS","B. Subacute combined degeneration of the cord due to vitamin B12 deficiency","C. Tropical spastic paraparesis (HTLV-1)","D. Syringomyelia"]','B','Subacute combined degeneration (SCD) of the cord is caused by vitamin B12 deficiency, affecting posterior columns (proprioception and vibration loss) and lateral corticospinal tracts (spastic paraparesis), producing a combined UMN and dorsal column syndrome. Macrocytosis (MCV above 100 fL), glossitis, and risk factors (alcohol, veganism, pernicious anaemia) support the diagnosis. Treatment: IM hydroxocobalamin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Spinal Cord Disorders','hard','mcq','A 30-year-old man develops neck pain followed over 3 days by bilateral arm weakness and dissociated sensory loss (pain and temperature impaired, proprioception intact) in a cape distribution across both arms and upper chest. MRI shows a central intramedullary fluid cavity at C4-C7. What is the diagnosis?','["A. MS plaque with posterior column predominant sensory loss","B. Syringomyelia with cape distribution dissociated sensory loss affecting arms and upper chest bilaterally","C. Anterior spinal artery infarction with loss of all modalities below the lesion","D. Transverse myelitis with complete sensory level"]','B','Syringomyelia (central cord cavity) disrupts decussating spinothalamic fibres at the level of the syrinx, causing dissociated sensory loss (pain and temperature loss, preserved proprioception and vibration) in a cape distribution (bilateral arms and upper chest). Lower limbs are spared initially. UMN signs develop below and LMN signs occur at the level of the syrinx. Often associated with Chiari malformation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed'),
('{"medicine"}','Medicine','CNS & Neurology','Clinicals','Spinal Cord Disorders','hard','mcq','A 55-year-old man with HIV (CD4 30 cells/microlitre) not on ART presents with progressive myelopathy. MRI shows T2 signal change in the posterior and lateral columns of the thoracic cord without enhancement. CSF shows only mildly elevated protein. What is the most likely cause?','["A. HTLV-1 associated myelopathy","B. HIV-associated vacuolar myelopathy","C. Spinal cord lymphoma","D. CMV myeloradiculitis"]','B','HIV-associated vacuolar myelopathy (VM) is the most common myelopathy in advanced HIV (CD4 below 200). Pathologically it resembles subacute combined degeneration with vacuolation of posterior and lateral white matter columns. It presents with spastic paraparesis and sensory ataxia. CSF is typically non-inflammatory. ART halts progression. Vitamin B12 deficiency must be excluded.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
